import re

# 시각 / 레벨 / [모듈] / 메시지 형식의 줄을 분해한다
LINE_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+(\w+)\s+\[([^\]]+)\]\s*(.*)$")


def parse_errors(path):
    # ERROR 줄만 (시각, 모듈, 메시지)로 모은다
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\n"))
            if m and m.group(2) == "ERROR":
                rows.append((m.group(1), m.group(3), m.group(4)))
    return rows


def to_markdown(rows):
    # 표 안에서 깨지지 않도록 | 를 이스케이프한다
    def esc(s):
        return s.replace("|", "\\|")

    lines = ["| 시각 | 모듈 | 메시지 |", "| --- | --- | --- |"]
    for row in rows:
        lines.append("| " + " | ".join(esc(c) for c in row) + " |")
    return "\n".join(lines) + "\n"


def main():
    rows = parse_errors("sample.log")
    with open("errors.md", "w", encoding="utf-8", newline="\n") as f:
        f.write(to_markdown(rows))


if __name__ == "__main__":
    main()

